parameters.jsCode:
// Define the fan-out plan: one platform = one rewrite call.
// Adjust platforms array per business needs.
// NOTE: `zalo_oa` intentionally NOT listed here — Zalo OA broadcast is not
// auto-published in v1 (see docs/12-zalo-oa-publish.md). Editorial team will
// broadcast the Facebook/TikTok draft manually via Zalo Business dashboard
// if needed. Re-enable once an official OA broadcast endpoint is wired.
const platforms = [
  { platform: 'facebook',
    spec: 'Facebook post VN 700-1200 ký tự, 1 hook + 3-5 hashtag.' },
  { platform: 'tiktok',
    spec: 'TikTok caption VN ≤150 ký tự + 5 hashtag trending. Hook 1 câu.' },
  { platform: 'linkedin',
    spec: 'LinkedIn post EN ≤1500 chars, professional tone, 3 hashtags.' }
];
const item = $json;
// Embed plannedCount into every child so the downstream Mark item drafted
// node can decide whether fan-out is complete without re-reading node state.
const plannedCount = platforms.length;
return platforms.map(p => ({ json: { ...item, ...p, plannedCount } }));

