parameters.jsCode:
const llm = JSON.parse($('Rewrite per platform').first().json.choices?.[0]?.message?.content || '{}');
const qa  = $json || { policyOk: true, plagiarism: 0, risk: 'low', notes: 'qa_skipped' };
const plan = $('Plan per-platform').item.json;
// Plan per-platform spreads the original item into each platform record, so
// `plan` already carries id/title/body/source/hero_image_url/canonical_url.
const status = qa.policyOk === false || qa.risk === 'high' ? 'rejected' : 'pending_review';
const scheduledAt = new Date(Date.now() + 2 * 3600 * 1000).toISOString();
const media = plan.hero_image_url ? [plan.hero_image_url] : [];
// queued_at semantics: non-NULL when the draft is editor-visible.
//   - rejected → terminal, no sheet push needed → set queued_at at INSERT time.
//   - pending_review → set queued_at AFTER successful Push to Review Queue.
const queuedAt = status === 'rejected' ? new Date().toISOString() : null;
return [{ json: {
  itemId: plan.id,
  orgId:  $env.ZALOCRM_ORG_ID,
  platform: plan.platform,
  variantKey: 'v1',
  body:   llm.body || '',
  hashtags: llm.hashtags || [],
  media,
  qaResult: qa,
  status,
  scheduledAt,
  queuedAt,
  title: plan.title,
  source: plan.source,
  canonicalUrl: plan.canonical_url
}}];
